#!/usr/bin/env node
/**
 * Safe database restore utility v3 from JSON backup generated by scripts/db-backup.mjs.
 * Supports backup v3 (tables, indexes, views, triggers, sequences, typed values including BLOB) and v2.
 * Restores into a local SQLite target OR an isolated Turso Cloud Staging restore database (--env staging).
 * Requires explicit --in and --confirm flags. Never touches remote Turso Production.
 *
 * Usage:
 *   node scripts/db-restore.mjs --in backup.json --target restored.sqlite --confirm
 *   node scripts/db-restore.mjs --env staging --in backup.json --confirm [--preflight-only]
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { DatabaseSync } from "node:sqlite";
import { createClient } from "@libsql/client";
import { validateStagingTarget } from "./lib/turso-preflight.mjs";
import {
  decodeRow,
  isValidIdentifier,
  validateBackupPayload,
} from "./lib/backup-format.mjs";

function getArg(flag) {
  const idx = process.argv.indexOf(flag);
  if (idx !== -1 && idx + 1 < process.argv.length) {
    return process.argv[idx + 1];
  }
  return null;
}

function makeIfNotExistsDdl(sql, kindRegex) {
  return sql.replace(kindRegex, (match) => `${match} IF NOT EXISTS`);
}

function getTableDefinitions(backup, version) {
  if (version === 3) {
    return backup.objects.tables.map((t) => ({ name: t.name, sql: t.sql }));
  }
  const schema = backup.schema && typeof backup.schema === "object" ? backup.schema : {};
  return Object.entries(schema)
    .filter(([name, sql]) => isValidIdentifier(name) && typeof sql === "string")
    .map(([name, sql]) => ({ name, sql }));
}

function assertRowCountsMatch(backup, restoredCounts) {
  if (!backup.rowCounts || typeof backup.rowCounts !== "object") return;
  for (const [tableName, expectedCount] of Object.entries(backup.rowCounts)) {
    if (restoredCounts[tableName] !== expectedCount) {
      throw new Error(
        `Row count mismatch on table "${tableName}": expected ${expectedCount}, restored ${restoredCounts[tableName]}. Re-run restore on a clean target database.`
      );
    }
  }
}

async function restoreViewsWithDependencies(views, execFn) {
  let pending = [...views];
  let lastError = null;

  while (pending.length > 0) {
    const nextPending = [];
    let progress = 0;

    for (const view of pending) {
      try {
        const safeSql = makeIfNotExistsDdl(view.sql, /^CREATE\s+VIEW\b(?!\s+IF\s+NOT\s+EXISTS)/i);
        await execFn(safeSql);
        progress += 1;
      } catch (err) {
        lastError = err;
        nextPending.push(view);
      }
    }

    if (progress === 0 && nextPending.length > 0) {
      const failingNames = nextPending.map((v) => v.name).join(", ");
      const reason = lastError instanceof Error ? lastError.message : String(lastError);
      throw new Error(
        `Failed to create view(s) [${failingNames}]: ${reason}. Re-run restore on a clean target database.`
      );
    }
    pending = nextPending;
  }
}

function isSubPath(childPath, parentPath) {
  const rel = path.relative(path.resolve(parentPath), path.resolve(childPath));
  return rel === "" || (!rel.startsWith("..") && !path.isAbsolute(rel));
}

export function validateLocalRestoreTarget(
  targetPath,
  {
    repoRoot = process.cwd(),
    approvedDir = process.env.RESTORE_APPROVED_DIR || os.tmpdir(),
  } = {}
) {
  const resolvedTarget = path.resolve(targetPath);
  const parentDir = path.dirname(resolvedTarget);

  if (!fs.existsSync(parentDir) || !fs.statSync(parentDir).isDirectory()) {
    throw new Error(
      `Restore blocked: target parent directory does not exist (${parentDir}). Create or specify an existing approved restore directory.`
    );
  }

  const repoBundledDb = path.resolve(repoRoot, "data", "gonoifc.sqlite");
  if (resolvedTarget.toLowerCase() === repoBundledDb.toLowerCase()) {
    throw new Error("Restore blocked: refusing to overwrite repository bundled database data/gonoifc.sqlite.");
  }

  if (isSubPath(resolvedTarget, repoRoot) && !isSubPath(resolvedTarget, approvedDir)) {
    throw new Error(
      `Restore blocked: local target (${resolvedTarget}) is inside repository root without approved restore directory.`
    );
  }

  if (!isSubPath(resolvedTarget, approvedDir)) {
    throw new Error(
      `Restore blocked: local target (${resolvedTarget}) is outside approved restore directory (${path.resolve(approvedDir)}).`
    );
  }

  return resolvedTarget;
}

export async function restoreToTursoStaging(backup, version, preflight, options = {}) {
  const client =
    options.client ||
    createClient({
      url: process.env.TURSO_STAGING_RESTORE_DATABASE_URL.trim(),
      authToken: process.env.TURSO_STAGING_RESTORE_AUTH_TOKEN.trim(),
    });

  const restoredCounts = {};
  const tableDefs = getTableDefinitions(backup, version);
  const schemaMap = Object.fromEntries(tableDefs.map((t) => [t.name, t.sql]));
  let mutationStarted = false;

  try {
    // 0. Target emptiness check (also rejects previously contaminated targets)
    const existingObjects = await client.execute(
      "SELECT name FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' LIMIT 1;"
    );
    if (existingObjects.rows.length > 0) {
      throw new Error(
        `Refusing restore: remote Staging restore target "${preflight.dbName}" is not empty (found "${String(existingObjects.rows[0].name)}"). Reset or provision a clean disposable target first.`
      );
    }

    await client.execute("PRAGMA foreign_keys = OFF;");
    mutationStarted = true;

    // 1. Create tables
    for (const { name, sql } of tableDefs) {
      try {
        const safeDdl = makeIfNotExistsDdl(sql, /^CREATE\s+TABLE\b(?!\s+IF\s+NOT\s+EXISTS)/i);
        await client.execute(safeDdl);
      } catch (err) {
        throw new Error(
          `Failed creating table "${name}": ${err instanceof Error ? err.message : String(err)}. Target marked contaminated.`
        );
      }
    }

    // 2. Restore row data (triggers are not created yet)
    for (const [tableName, rows] of Object.entries(backup.tables)) {
      if (!isValidIdentifier(tableName) || !Array.isArray(rows)) continue;

      if (!schemaMap[tableName] && rows.length > 0) {
        const fallbackCols = Object.keys(rows[0])
          .filter((c) => isValidIdentifier(c))
          .map((c) => `"${c}" TEXT`)
          .join(", ");
        if (fallbackCols) {
          await client.execute(`CREATE TABLE IF NOT EXISTS "${tableName}" (${fallbackCols});`);
        }
      }

      if (rows.length === 0) {
        restoredCounts[tableName] = 0;
        continue;
      }

      const decodedRows = rows.map((r) => decodeRow(r));
      const cols = Object.keys(decodedRows[0]).filter((c) => isValidIdentifier(c));
      if (cols.length === 0) continue;

      await client.execute(`DELETE FROM "${tableName}";`);
      const placeholders = cols.map(() => "?").join(", ");
      const insertSql = `INSERT INTO "${tableName}" (${cols.map((c) => `"${c}"`).join(", ")}) VALUES (${placeholders})`;

      for (const row of decodedRows) {
        try {
          await client.execute({
            sql: insertSql,
            args: cols.map((c) => (row[c] === undefined ? null : row[c])),
          });
        } catch (err) {
          throw new Error(
            `Failed inserting row into table "${tableName}": ${err instanceof Error ? err.message : String(err)}. Target marked contaminated.`
          );
        }
      }
      restoredCounts[tableName] = decodedRows.length;
    }

    const objectCounts = {
      tables: tableDefs.length,
      indexes: 0,
      views: 0,
      triggers: 0,
    };

    if (version === 3) {
      // 3. Create indexes
      for (const idx of backup.objects.indexes) {
        try {
          const safeSql = makeIfNotExistsDdl(
            idx.sql,
            /^CREATE\s+(?:UNIQUE\s+)?INDEX\b(?!\s+IF\s+NOT\s+EXISTS)/i
          );
          await client.execute(safeSql);
          objectCounts.indexes += 1;
        } catch (err) {
          throw new Error(
            `Failed creating index "${idx.name}": ${err instanceof Error ? err.message : String(err)}. Target marked contaminated.`
          );
        }
      }

      // 4. Create views in dependency order
      await restoreViewsWithDependencies(backup.objects.views, (sql) => client.execute(sql));
      objectCounts.views = backup.objects.views.length;

      // 5. Create triggers AFTER historical data is restored
      for (const trg of backup.objects.triggers) {
        try {
          const safeSql = makeIfNotExistsDdl(
            trg.sql,
            /^CREATE\s+TRIGGER\b(?!\s+IF\s+NOT\s+EXISTS)/i
          );
          await client.execute(safeSql);
          objectCounts.triggers += 1;
        } catch (err) {
          throw new Error(
            `Failed creating trigger "${trg.name}": ${err instanceof Error ? err.message : String(err)}. Target marked contaminated.`
          );
        }
      }

      // 5b. Restore sqlite_sequence for AUTOINCREMENT tables
      if (Array.isArray(backup.sequences) && backup.sequences.length > 0) {
        for (const seqEntry of backup.sequences) {
          if (!isValidIdentifier(seqEntry.name)) continue;
          try {
            await client.execute({
              sql: "DELETE FROM sqlite_sequence WHERE name = ?",
              args: [seqEntry.name],
            });
            await client.execute({
              sql: `INSERT INTO sqlite_sequence (name, seq) VALUES (?, MAX(?, COALESCE((SELECT MAX(rowid) FROM "${seqEntry.name}"), 0)))`,
              args: [seqEntry.name, seqEntry.seq],
            });
          } catch (err) {
            throw new Error(
              `Failed restoring sqlite_sequence for "${seqEntry.name}": ${err instanceof Error ? err.message : String(err)}. Target marked contaminated.`
            );
          }
        }
      }
    }

    // 6. Foreign key & integrity checks
    await client.execute("PRAGMA foreign_keys = ON;");
    const fkCheckRes = await client.execute("PRAGMA foreign_key_check;");
    if (fkCheckRes.rows.length > 0) {
      throw new Error(
        `Foreign key integrity check failed (${fkCheckRes.rows.length} violation(s)). Target marked contaminated.`
      );
    }

    const integrityRes = await client.execute("PRAGMA integrity_check;");
    if (
      integrityRes.rows.length !== 1 ||
      integrityRes.rows[0]?.integrity_check !== "ok"
    ) {
      throw new Error("SQLite integrity_check failed on Staging restore target. Target marked contaminated.");
    }

    // 7. Verify row counts
    assertRowCountsMatch(backup, restoredCounts);

    const summary = {
      status: "ok",
      version,
      mode: "staging-restore",
      targetHost: preflight.safeHost,
      dbName: preflight.dbName,
      objectCounts,
      restoredCounts,
    };
    console.log(JSON.stringify(summary, null, 2));
    return summary;
  } catch (err) {
    if (mutationStarted) {
      try {
        await client.execute(
          "CREATE TABLE IF NOT EXISTS _restore_contaminated (failed_at TEXT NOT NULL, reason TEXT NOT NULL);"
        );
        await client.execute({
          sql: "INSERT INTO _restore_contaminated (failed_at, reason) VALUES (?, ?);",
          args: [
            new Date().toISOString(),
            (err instanceof Error ? err.message : String(err)).slice(0, 500),
          ],
        });
      } catch {
        // Best-effort contamination marker; never mask original failure
      }
      if (err && typeof err === "object") {
        err.contaminated = true;
      }
    }
    throw err;
  } finally {
    if (!options.keepClientOpen) {
      client.close();
    }
  }
}

export async function restoreToLocalSqlite(backup, version, resolvedTarget, options = {}) {
  const existingSize = fs.existsSync(resolvedTarget) ? fs.statSync(resolvedTarget).size : 0;
  if (existingSize > 0) {
    const checkDb = new DatabaseSync(resolvedTarget);
    try {
      const existingObjects = checkDb
        .prepare("SELECT name FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' LIMIT 1;")
        .all();
      if (existingObjects.length > 0) {
        throw new Error(
          `Refusing restore: target SQLite database (${resolvedTarget}) is not empty (found "${String(existingObjects[0].name)}").`
        );
      }
    } finally {
      checkDb.close();
    }
  }

  const db = new DatabaseSync(resolvedTarget);
  const hooks = options.hooks || {};

  const restoredCounts = {};
  const tableDefs = getTableDefinitions(backup, version);
  const schemaMap = Object.fromEntries(tableDefs.map((t) => [t.name, t.sql]));
  let inTx = false;
  let commitUncertain = false;

  try {
    db.exec("PRAGMA foreign_keys = OFF;");
    db.exec("BEGIN IMMEDIATE;");
    inTx = true;

    // 1. Create tables
    for (const { name, sql } of tableDefs) {
      try {
        const safeDdl = makeIfNotExistsDdl(sql, /^CREATE\s+TABLE\b(?!\s+IF\s+NOT\s+EXISTS)/i);
        db.exec(safeDdl);
      } catch (err) {
        throw new Error(
          `Failed creating table "${name}": ${err instanceof Error ? err.message : String(err)}.`
        );
      }
    }

    // 2. Restore rows preserving native SQLite types (including BLOB)
    for (const [tableName, rows] of Object.entries(backup.tables)) {
      if (!isValidIdentifier(tableName) || !Array.isArray(rows)) continue;

      if (!schemaMap[tableName] && rows.length > 0) {
        const fallbackCols = Object.keys(rows[0])
          .filter((c) => isValidIdentifier(c))
          .map((c) => `"${c}" TEXT`)
          .join(", ");
        if (fallbackCols) {
          db.exec(`CREATE TABLE IF NOT EXISTS "${tableName}" (${fallbackCols});`);
        }
      }

      if (rows.length === 0) {
        restoredCounts[tableName] = 0;
        continue;
      }

      const decodedRows = rows.map((r) => decodeRow(r));
      const cols = Object.keys(decodedRows[0]).filter((c) => isValidIdentifier(c));
      if (cols.length === 0) continue;

      db.exec(`DELETE FROM "${tableName}";`);
      const placeholders = cols.map(() => "?").join(", ");
      const stmt = db.prepare(
        `INSERT INTO "${tableName}" (${cols.map((c) => `"${c}"`).join(", ")}) VALUES (${placeholders})`
      );

      for (let rowIdx = 0; rowIdx < decodedRows.length; rowIdx += 1) {
        const row = decodedRows[rowIdx];
        if (typeof hooks.onBeforeRowInsert === "function") {
          hooks.onBeforeRowInsert(tableName, rowIdx);
        }
        try {
          stmt.run(...cols.map((c) => (row[c] === undefined ? null : row[c])));
        } catch (err) {
          throw new Error(
            `Failed inserting row into table "${tableName}": ${err instanceof Error ? err.message : String(err)}.`
          );
        }
      }
      restoredCounts[tableName] = decodedRows.length;
    }

    const objectCounts = {
      tables: tableDefs.length,
      indexes: 0,
      views: 0,
      triggers: 0,
    };

    if (version === 3) {
      // 3. Create indexes
      for (const idx of backup.objects.indexes) {
        if (typeof hooks.onBeforeIndexCreate === "function") {
          hooks.onBeforeIndexCreate(idx.name);
        }
        try {
          const safeSql = makeIfNotExistsDdl(
            idx.sql,
            /^CREATE\s+(?:UNIQUE\s+)?INDEX\b(?!\s+IF\s+NOT\s+EXISTS)/i
          );
          db.exec(safeSql);
          objectCounts.indexes += 1;
        } catch (err) {
          throw new Error(
            `Failed creating index "${idx.name}": ${err instanceof Error ? err.message : String(err)}.`
          );
        }
      }

      // 4. Create views in dependency order
      await restoreViewsWithDependencies(backup.objects.views, (sql) => {
        db.exec(sql);
      });
      objectCounts.views = backup.objects.views.length;

      // 5. Create triggers AFTER historical data is restored
      for (const trg of backup.objects.triggers) {
        try {
          const safeSql = makeIfNotExistsDdl(
            trg.sql,
            /^CREATE\s+TRIGGER\b(?!\s+IF\s+NOT\s+EXISTS)/i
          );
          db.exec(safeSql);
          objectCounts.triggers += 1;
        } catch (err) {
          throw new Error(
            `Failed creating trigger "${trg.name}": ${err instanceof Error ? err.message : String(err)}.`
          );
        }
      }

      // 5b. Restore sqlite_sequence for AUTOINCREMENT tables
      if (Array.isArray(backup.sequences) && backup.sequences.length > 0) {
        for (const seqEntry of backup.sequences) {
          if (!isValidIdentifier(seqEntry.name)) continue;
          if (typeof hooks.onBeforeSequenceRestore === "function") {
            hooks.onBeforeSequenceRestore(seqEntry.name);
          }
          try {
            db.prepare("DELETE FROM sqlite_sequence WHERE name = ?").run(seqEntry.name);
            db.prepare(
              `INSERT INTO sqlite_sequence (name, seq) VALUES (?, MAX(?, COALESCE((SELECT MAX(rowid) FROM "${seqEntry.name}"), 0)))`
            ).run(seqEntry.name, seqEntry.seq);
          } catch (err) {
            throw new Error(
              `Failed restoring sqlite_sequence for "${seqEntry.name}": ${err instanceof Error ? err.message : String(err)}.`
            );
          }
        }
      }
    }

    // 6. Foreign key check & integrity_check inside transaction before COMMIT
    const fkViolations = db.prepare("PRAGMA foreign_key_check;").all();
    if (fkViolations.length > 0) {
      throw new Error(
        `Foreign key integrity check failed (${fkViolations.length} violation(s)).`
      );
    }

    const integrityRows =
      typeof hooks.overrideIntegrityCheck === "function"
        ? hooks.overrideIntegrityCheck()
        : db.prepare("PRAGMA integrity_check;").all();
    if (
      !Array.isArray(integrityRows) ||
      integrityRows.length !== 1 ||
      integrityRows[0]?.integrity_check !== "ok"
    ) {
      throw new Error("SQLite integrity_check failed.");
    }

    // 7. Verify row counts
    assertRowCountsMatch(backup, restoredCounts);

    if (typeof hooks.onBeforeCommit === "function") {
      commitUncertain = true;
      hooks.onBeforeCommit();
    }
    db.exec("COMMIT;");
    inTx = false;
    commitUncertain = false;
    db.exec("PRAGMA foreign_keys = ON;");

    const summary = {
      status: "ok",
      version,
      target: resolvedTarget,
      schemaTables: tableDefs.length,
      objectCounts,
      restoredCounts,
    };
    console.log(JSON.stringify(summary, null, 2));
    return summary;
  } catch (err) {
    if (inTx && !commitUncertain) {
      try {
        db.exec("ROLLBACK;");
      } catch {
        // Best-effort rollback; preserve original error
      }
    }
    throw err;
  } finally {
    db.close();
  }
}

async function main() {
  const envMode = getArg("--env");
  const preflightOnly = process.argv.includes("--preflight-only");
  const inPath = getArg("--in");
  const targetPath = getArg("--target");
  const confirmed = process.argv.includes("--confirm");

  if (envMode === "staging") {
    if (targetPath) {
      console.error("Preflight blocked: --target cannot be combined with --env staging.");
      process.exit(1);
    }
    const preflight = validateStagingTarget({
      url: process.env.TURSO_STAGING_RESTORE_DATABASE_URL,
      token: process.env.TURSO_STAGING_RESTORE_AUTH_TOKEN,
      envUrlName: "TURSO_STAGING_RESTORE_DATABASE_URL",
      envTokenName: "TURSO_STAGING_RESTORE_AUTH_TOKEN",
      role: "target",
      disallowUrls: [
        process.env.TURSO_DATABASE_URL,
        process.env.TURSO_STAGING_DATABASE_URL,
      ],
    });
    if (preflightOnly) {
      console.log(
        JSON.stringify({ status: "preflight_ok", mode: "staging-restore", ...preflight }, null, 2)
      );
      return;
    }
    if (!inPath || !confirmed) {
      console.error("Usage: node scripts/db-restore.mjs --env staging --in <backup.json> --confirm");
      process.exit(1);
    }
    const resolvedIn = path.resolve(inPath);
    if (!fs.existsSync(resolvedIn)) {
      console.error(`Backup file not found: ${resolvedIn}`);
      process.exit(1);
    }
    const backup = JSON.parse(fs.readFileSync(resolvedIn, "utf8"));
    const { version } = validateBackupPayload(backup);
    await restoreToTursoStaging(backup, version, preflight);
    return;
  } else if (envMode) {
    console.error(`Unsupported --env value "${envMode}". Expected "staging".`);
    process.exit(1);
  }

  if (!inPath || !targetPath || !confirmed) {
    console.error(
      "Usage: node scripts/db-restore.mjs --in <backup.json> --target <target.sqlite> --confirm"
    );
    process.exit(1);
  }

  const resolvedIn = path.resolve(inPath);
  if (!fs.existsSync(resolvedIn)) {
    console.error(`Backup file not found: ${resolvedIn}`);
    process.exit(1);
  }

  const resolvedTarget = validateLocalRestoreTarget(targetPath);
  const backup = JSON.parse(fs.readFileSync(resolvedIn, "utf8"));
  const { version } = validateBackupPayload(backup);
  await restoreToLocalSqlite(backup, version, resolvedTarget);
}

const isMainModule =
  typeof process.argv[1] === "string" &&
  import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href;

if (isMainModule) {
  main().catch((err) => {
    console.error(err instanceof Error ? err.message : String(err));
    process.exit(1);
  });
}
